/* From Uiverse.io by arshshaikh06 - Source: https://www.behance.net/gallery/117113957/Social-Share-Animation-Daily-UI-010 - Tags: button, hover, hover button, css button, css animation, cool button, button hover effect  */
.__UIV_SCOPE__ #button-container {
  position: relative;
}

.__UIV_SCOPE__ .button {
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% 50%;
  background: #F4F7F5;
  border: none;
  border-radius: 25px;
  height: 50px;
  width: 50px;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: 0.3s ease-in;
}

.__UIV_SCOPE__ #share {
  color: #DC0654;
  background: #fbe6ed;
}

.__UIV_SCOPE__ #facebook {
  background: linear-gradient(-160deg, #00D2FF, #3A7BD5);
}

.__UIV_SCOPE__ #instagram {
  background: linear-gradient(135deg, #833AB4, #FD1D1D, #FCB045);
}

.__UIV_SCOPE__ #dribbble {
  background: linear-gradient(-70deg, #D70652, #FF025E);
}

.__UIV_SCOPE__ #github {
  background: linear-gradient(-70deg, #171515, #FF025E);
}

.__UIV_SCOPE__ #youtube {
  background: #FF0000;
}

.__UIV_SCOPE__ #button-container:hover button {
  rotate: 360deg;
}

.__UIV_SCOPE__ #button-container:hover #share {
  rotate: 270deg;
}

.__UIV_SCOPE__ #button-container:hover > #facebook {
  translate: -300% 50%;
}

.__UIV_SCOPE__ #button-container:hover > #instagram {
  translate: -226.78% -126.78%;
}

.__UIV_SCOPE__ #button-container:hover > #dribbble {
  translate: -50% -200%;
}

.__UIV_SCOPE__ #button-container:hover > #github {
  translate: 126.78% -126.78%;
}

.__UIV_SCOPE__ #button-container:hover > #youtube {
  translate: 200% 50%;
}
